// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

/**
 * How far a row estimate can lie from the rows a plan really emits, as the factors {@code down} and {@code up} of a
 * q-error: the real count is expected between {@code estimate / down} and {@code estimate * up}. An infinite factor
 * means nothing bounds that side of the estimate.
 * <p>
 * The errors of the estimates in a join are independent, so they rarely all point the same way: they add in quadrature
 * on a log scale rather than multiplying. Measured on the 3000-person regret harness, 2026-11-05: multiplied spreads
 * reached 1000 times the expected cost while the measured cost stayed within about 4 times it at every depth.
 */
record LmdbNativeRowSpread(double down, double up) {

	/** An estimate that is the real count. */
	static final LmdbNativeRowSpread EXACT = new LmdbNativeRowSpread(1D, 1D);

	/** A plan kind with no statistic behind its row count. */
	static final LmdbNativeRowSpread UNKNOWN = new LmdbNativeRowSpread(Double.POSITIVE_INFINITY,
			Double.POSITIVE_INFINITY);

	/** A pattern's whole population as the store estimated it. */
	static final LmdbNativeRowSpread SCAN = new LmdbNativeRowSpread(1.5D, 1.5D);

	/**
	 * One probe, or a run of them, priced by a predicate's mean fan-out: it holds across many keys, not for one. A mean
	 * overstates a probe more than it understates one, because many keys hit nothing.
	 */
	static final LmdbNativeRowSpread PROBE = new LmdbNativeRowSpread(3D, 2D);

	/** A count from the structure of a plan rather than from statistics: a pseudo-cardinality or a path's reach. */
	static final LmdbNativeRowSpread STRUCTURAL = new LmdbNativeRowSpread(16D, 16D);

	/** The spread of a product of two independent estimates. */
	LmdbNativeRowSpread times(LmdbNativeRowSpread other) {
		return new LmdbNativeRowSpread(combined(down, other.down), combined(up, other.up));
	}

	/** Two independent factors of at least 1 taken together: their logs add in quadrature. */
	static double combined(double left, double right) {
		if (Double.isInfinite(left) || Double.isInfinite(right)) {
			return Double.POSITIVE_INFINITY;
		}
		return Math.exp(Math.hypot(Math.log(left), Math.log(right)));
	}

	/** The spread of a sum of two estimates: never wider than the wider part. */
	LmdbNativeRowSpread widest(LmdbNativeRowSpread other) {
		return new LmdbNativeRowSpread(Math.max(down, other.down), Math.max(up, other.up));
	}

	/** The same ceiling with no floor, for a plan that can reject every row its input gives it. */
	LmdbNativeRowSpread mayRejectAll() {
		return new LmdbNativeRowSpread(Double.POSITIVE_INFINITY, up);
	}

	/** The same floor with the ceiling limited to {@code factor}. */
	LmdbNativeRowSpread upAtMost(double factor) {
		return new LmdbNativeRowSpread(down, Math.max(1D, Math.min(up, factor)));
	}

	boolean known() {
		return Double.isFinite(up);
	}
}
